// Rules the brief requires, stated independently of the spec's derive().
const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL = ['completed', 'failed', 'cancelled'];
const tasks = (s) => [s.task0, s.task1, s.task2];
const same = (a, b) => a.status === b.status && a.task0 === b.task0 && a.task1 === b.task1 && a.task2 === b.task2;

const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
};

export const stateInvariants = [
  { name: 'no-run-means-no-tasks', pred: (s) => (s.status === 'none') === tasks(s).every((t) => t === 'none') },
  { name: 'completed-iff-every-task-completed', pred: (s) => s.status === 'none' || (s.status === 'completed') === tasks(s).every((t) => t === 'completed') },
  { name: 'failed-whenever-a-task-failed', pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'failed-only-if-a-task-failed', pred: (s) => s.status !== 'failed' || tasks(s).includes('failed') },
  { name: 'never-completed-or-cancelled-while-in-flight', pred: (s) => !['completed', 'cancelled'].includes(s.status) || !tasks(s).some((t) => IN_FLIGHT.includes(t)) },
  { name: 'uniform-tasks-give-their-status', pred: (s) => !(s.task0 === s.task1 && s.task1 === s.task2) || s.status === s.task0 },
  { name: 'mixed-in-flight-without-failure-is-running', pred: (s) => {
    const ts = tasks(s);
    if (ts[0] === ts[1] && ts[1] === ts[2]) return true;
    if (ts.includes('failed') || !ts.some((t) => IN_FLIGHT.includes(t))) return true;
    return s.status === 'running';
  } },
];

export const transitionInvariants = [
  { name: 'closed-run-never-changes', pred: (pre, a, d, post) => !FINAL.includes(pre.status) || same(pre, post) },
  { name: 'start-only-creates-all-queued', pred: (pre, a, d, post) => a !== 'START' || same(pre, post) ||
      (pre.status === 'none' && post.status === 'queued' && tasks(post).every((t) => t === 'queued')) },
  { name: 'task-report-moves-exactly-the-named-task-legally', pred: (pre, a, d, post) => {
    if (!MOVES[a] || same(pre, post)) return true;
    const [from, to] = MOVES[a];
    return [0, 1, 2].every((i) => i === d.task
      ? pre[`task${i}`] === from && post[`task${i}`] === to
      : pre[`task${i}`] === post[`task${i}`]);
  } },
  { name: 'cancel-cancels-exactly-the-in-flight-tasks', pred: (pre, a, d, post) => a !== 'CANCEL' || same(pre, post) ||
      [0, 1, 2].every((i) => post[`task${i}`] === (IN_FLIGHT.includes(pre[`task${i}`]) ? 'cancelled' : pre[`task${i}`])) },
  { name: 'final-tasks-stay-final', pred: (pre, a, d, post) => [0, 1, 2].every((i) => !FINAL.includes(pre[`task${i}`]) || pre[`task${i}`] === post[`task${i}`]) },
];

export const rejectionInvariants = [
  { name: 'closed-run-refuses-everything', pred: (s, a, d, v) => !FINAL.includes(s.status) || (v && v.rejected) },
  { name: 'unknown-run-refuses-all-but-start', pred: (s, a, d, v) => s.status !== 'none' || a === 'START' || (v && v.rejected) },
  { name: 'bad-task-number-refused', pred: (s, a, d, v) => !MOVES[a] || [0, 1, 2].includes(d.task) || (v && v.rejected) },
  { name: 'cancel-refused-with-nothing-in-flight', pred: (s, a, d, v) => a !== 'CANCEL' || tasks(s).some((t) => IN_FLIGHT.includes(t)) || (v && v.rejected) },
];

