// @ts-nocheck -- node:test types are not installed
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('start, unknown runs, duplicates', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('happy path to completed, then closed', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('r', t)).ok, true);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r')).status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('mixed queued/running is running; all evicted is evicted', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskStarted('r', 0);
  await h.taskStarted('r', 2);
  for (const t of [0, 1, 2]) await h.taskEvicted('r', t);
  assert.equal((await h.run('r')).status, 'evicted');
  await h.taskRequeued('r', 0);
  assert.equal((await h.run('r')).status, 'running');
});

test('failure closes the run', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskStarted('r', 1)).ok, false);
});

test('cancel: completed tasks stay, run is cancelled', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancel('r'), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
});

test('bad moves and bad task numbers are refused and change nothing', async () => {
  const h = await createHost();
  await h.start('r');
  const before = await h.run('r');
  for (const bad of [-1, 3, 1.5, NaN]) assert.equal((await h.taskStarted('r', bad)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskEvicted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  const res = await h.taskFailed('r', 0);
  assert.equal(res.ok, false);
  assert.equal(typeof res.reason, 'string');
  assert.deepEqual(await h.run('r'), before);
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  const b = await createHost();
