const TASK_KEYS = ['task0', 'task1', 'task2'];

const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.includes('failed')) return 'failed';
  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
  return 'cancelled';
};

const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
// A fresh intent definition per name: the library tags each action function.
