const INITIAL_STATE = { status: 'none', task0: 'none', task1: 'none', task2: 'none', paused: false };

const IN_FLIGHT = ['queued', 'running', 'evicted'];
// Run statuses that refuse every command (a failed run can still retry).
const CLOSED = ['completed', 'cancelled'];
const TASK_KEYS = ['task0', 'task1', 'task2'];

const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.includes('failed')) return 'failed';
  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
  return 'cancelled';
};

const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
// A fresh intent definition per name: the library tags each action function.
const taskIntent = () => ({ action: (data = {}) => ({ ...data }), schema: { task: { type: 'number', required: true } }, domain: TASK_DOMAIN });
const plainIntent = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

// A task report: the named task must sit in `from` (one status or a list); it
// moves to `to`. `blockedWhenPaused`: refused while the run is paused.
const move = (from, to, blockedWhenPaused = false) => (model) => (proposal, { reject, next, unchanged }) => {
  const froms = Array.isArray(from) ? from : [from];
  if (model.status === 'none') return reject('unknown-run');
  if (CLOSED.includes(model.status)) return reject('run-closed');
  if (blockedWhenPaused && model.paused) return reject('run-paused');
  const i = proposal.task;
  if (!Number.isInteger(i) || i < 0 || i > 2) return reject('no-such-task');
  const key = TASK_KEYS[i];
  if (!froms.includes(model[key])) return reject('illegal-task-move');
  const ts = TASK_KEYS.map((k) => (k === key ? to : model[k]));
  next.task0 = ts[0];
  next.task1 = ts[1];
  next.task2 = ts[2];
  next.status = derive(ts);
  unchanged('paused');
};

const setPaused = (paused) => (model) => (proposal, { reject, next, unchanged }) => {
  if (model.status === 'none') return reject('unknown-run');
  if (CLOSED.includes(model.status)) return reject('run-closed');
  if (model.paused === paused) return reject(paused ? 'already-paused' : 'not-paused');
  next.paused = paused;
  unchanged('status', 'task0', 'task1', 'task2');
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      task2: { type: 'string' },
      paused: { type: 'boolean' },
    },
    actions: {
      START: plainIntent(),
      TASK_STARTED: taskIntent(),
      TASK_COMPLETED: taskIntent(),
      TASK_FAILED: taskIntent(),
      TASK_EVICTED: taskIntent(),
      TASK_REQUEUED: taskIntent(),
      TASK_RETRIED: taskIntent(),
      CANCEL_TASK: taskIntent(),
      CANCEL: plainIntent(),
      PAUSE: plainIntent(),
      RESUME: plainIntent(),
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'none') return reject('run-exists');
        next.status = 'queued';
        next.task0 = 'queued';
        next.task1 = 'queued';
        next.task2 = 'queued';
        next.paused = false;
      },
      TASK_STARTED: move('queued', 'running', true),
      TASK_COMPLETED: move('running', 'completed'),
      TASK_FAILED: move('running', 'failed'),
      TASK_EVICTED: move('running', 'evicted'),
      TASK_REQUEUED: move('evicted', 'queued'),
      TASK_RETRIED: move('failed', 'queued'),
      CANCEL_TASK: move(IN_FLIGHT, 'cancelled'),
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-run');
        if (CLOSED.includes(model.status)) return reject('run-closed');
        const pre = TASK_KEYS.map((k) => model[k]);
        if (!pre.some((t) => IN_FLIGHT.includes(t))) return reject('nothing-in-flight');
        const ts = pre.map((t) => (IN_FLIGHT.includes(t) ? 'cancelled' : t));
        next.task0 = ts[0];
        next.task1 = ts[1];
        next.task2 = ts[2];
        next.status = derive(ts);
        unchanged('paused');
      },
      PAUSE: setPaused(true),
      RESUME: setPaused(false),
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
  TASK_FAILED: (data = {}) => intents.TASK_FAILED(data),
  TASK_EVICTED: (data = {}) => intents.TASK_EVICTED(data),
  TASK_REQUEUED: (data = {}) => intents.TASK_REQUEUED(data),
  TASK_RETRIED: (data = {}) => intents.TASK_RETRIED(data),
  CANCEL_TASK: (data = {}) => intents.CANCEL_TASK(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  PAUSE: (data = {}) => intents.PAUSE(data),
  RESUME: (data = {}) => intents.RESUME(data),
};

module.exports = { instance, init, actions, getState, setState };

