// Rules the brief requires, stated independently of the spec's derive().
const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL = ['completed', 'failed', 'cancelled'];
// Run statuses that refuse every command; a failed run still takes retries.
const CLOSED = ['completed', 'cancelled'];
// Task statuses no command ever leaves (failed is left by a retry).
const STUCK = ['completed', 'cancelled'];
const tasks = (s) => [s.task0, s.task1, s.task2];
const sameTasks = (a, b) => a.status === b.status && a.task0 === b.task0 && a.task1 === b.task1 && a.task2 === b.task2;
const same = (a, b) => sameTasks(a, b) && a.paused === b.paused;
const isOpen = (s) => s.status !== 'none' && !CLOSED.includes(s.status);

const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
  TASK_RETRIED: ['failed', 'queued'],
  CANCEL_TASK: [IN_FLIGHT, 'cancelled'],
};
const fromOk = (from, t) => (Array.isArray(from) ? from.includes(t) : from === t);

export const stateInvariants = [
  { name: 'no-run-means-no-tasks', pred: (s) => (s.status === 'none') === tasks(s).every((t) => t === 'none') },
  { name: 'no-run-is-not-paused', pred: (s) => s.status !== 'none' || s.paused === false },
  { name: 'completed-iff-every-task-completed', pred: (s) => s.status === 'none' || (s.status === 'completed') === tasks(s).every((t) => t === 'completed') },
  { name: 'failed-whenever-a-task-failed', pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'failed-only-if-a-task-failed', pred: (s) => s.status !== 'failed' || tasks(s).includes('failed') },
  { name: 'never-completed-or-cancelled-while-in-flight', pred: (s) => !['completed', 'cancelled'].includes(s.status) || !tasks(s).some((t) => IN_FLIGHT.includes(t)) },
  { name: 'uniform-tasks-give-their-status', pred: (s) => !(s.task0 === s.task1 && s.task1 === s.task2) || s.status === s.task0 },
  { name: 'mixed-in-flight-without-failure-is-running', pred: (s) => {
    const ts = tasks(s);
    if (ts[0] === ts[1] && ts[1] === ts[2]) return true;
    if (ts.includes('failed') || !ts.some((t) => IN_FLIGHT.includes(t))) return true;
    return s.status === 'running';
  } },
];

export const transitionInvariants = [
  { name: 'closed-run-never-changes', pred: (pre, a, d, post) => !CLOSED.includes(pre.status) || same(pre, post) },
  { name: 'failed-run-can-retry', pred: (pre, a, d, post) => !(a === 'TASK_RETRIED' && pre.status === 'failed' && pre[`task${d.task}`] === 'failed') ||
      post[`task${d.task}`] === 'queued' },
  { name: 'cancel-task-takes-effect-on-in-flight-task-of-open-run', pred: (pre, a, d, post) =>
      !(a === 'CANCEL_TASK' && !['none', ...CLOSED].includes(pre.status) && IN_FLIGHT.includes(pre[`task${d.task}`])) ||
      post[`task${d.task}`] === 'cancelled' },
  { name: 'start-only-creates-all-queued-unpaused', pred: (pre, a, d, post) => a !== 'START' || same(pre, post) ||
      (pre.status === 'none' && post.status === 'queued' && tasks(post).every((t) => t === 'queued') && post.paused === false) },
  { name: 'paused-flag-changes-only-by-pause-or-resume', pred: (pre, a, d, post) =>
      pre.paused === post.paused || a === 'START' || (a === 'PAUSE' && post.paused) || (a === 'RESUME' && !post.paused) },
  { name: 'pause-and-resume-leave-status-and-tasks', pred: (pre, a, d, post) => !['PAUSE', 'RESUME'].includes(a) || sameTasks(pre, post) },
  { name: 'nothing-starts-while-paused', pred: (pre, a, d, post) => !pre.paused ||
      [0, 1, 2].every((i) => !(pre[`task${i}`] !== 'running' && post[`task${i}`] === 'running')) },
  { name: 'task-report-moves-exactly-the-named-task-legally', pred: (pre, a, d, post) => {
    if (!MOVES[a] || same(pre, post)) return true;
    const [from, to] = MOVES[a];
    return [0, 1, 2].every((i) => i === d.task
      ? fromOk(from, pre[`task${i}`]) && post[`task${i}`] === to
      : pre[`task${i}`] === post[`task${i}`]);
  } },
  { name: 'cancel-cancels-exactly-the-in-flight-tasks', pred: (pre, a, d, post) => a !== 'CANCEL' || same(pre, post) ||
      [0, 1, 2].every((i) => post[`task${i}`] === (IN_FLIGHT.includes(pre[`task${i}`]) ? 'cancelled' : pre[`task${i}`])) },
  { name: 'completed-and-cancelled-tasks-stay', pred: (pre, a, d, post) => [0, 1, 2].every((i) => !STUCK.includes(pre[`task${i}`]) || pre[`task${i}`] === post[`task${i}`]) },
  { name: 'failed-task-leaves-only-by-retry', pred: (pre, a, d, post) => [0, 1, 2].every((i) => pre[`task${i}`] !== 'failed' || post[`task${i}`] === 'failed' ||
      (a === 'TASK_RETRIED' && d.task === i && post[`task${i}`] === 'queued')) },
];

export const rejectionInvariants = [
  { name: 'closed-run-refuses-everything', pred: (s, a, d, v) => !CLOSED.includes(s.status) || (v && v.rejected) },
  { name: 'retry-refused-unless-task-failed', pred: (s, a, d, v) => a !== 'TASK_RETRIED' || s[`task${d.task}`] === 'failed' || (v && v.rejected) },
  { name: 'cancel-task-refused-for-final-task', pred: (s, a, d, v) => a !== 'CANCEL_TASK' || !FINAL.includes(s[`task${d.task}`]) || (v && v.rejected) },
  { name: 'unknown-run-refuses-all-but-start', pred: (s, a, d, v) => s.status !== 'none' || a === 'START' || (v && v.rejected) },
  { name: 'bad-task-number-refused', pred: (s, a, d, v) => !MOVES[a] || [0, 1, 2].includes(d.task) || (v && v.rejected) },
  { name: 'cancel-refused-with-nothing-in-flight', pred: (s, a, d, v) => a !== 'CANCEL' || tasks(s).some((t) => IN_FLIGHT.includes(t)) || (v && v.rejected) },
];

