// @ts-nocheck -- node:test types are not installed
// Lockstep conformance: every (reachable state, action) of the polygraph spec is
// replayed on the real implementation, which must agree on ok/refused and on
// the resulting run view.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadSpec, stable } from '../tools/polygraph/scripts/load-spec.mjs';
import createHost from '../src/host.impl.ts';

const spec = loadSpec(new URL('../spec/run.spec.cjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const TASKS = [0, 1, 2, 3, -1];
const STEPS = [
  { action: 'START', data: {} },
  { action: 'CANCEL', data: {} },
  ...['TASK_STARTED', 'TASK_COMPLETED', 'TASK_FAILED', 'TASK_EVICTED', 'TASK_REQUEUED', 'TASK_RETRIED', 'CANCEL_TASK']
    .flatMap((action) => TASKS.map((task) => ({ action, data: { task } }))),
];
const METHOD = {
  START: 'start', CANCEL: 'cancel', TASK_STARTED: 'taskStarted', TASK_COMPLETED: 'taskCompleted',
  TASK_FAILED: 'taskFailed', TASK_EVICTED: 'taskEvicted', TASK_REQUEUED: 'taskRequeued',
  TASK_RETRIED: 'taskRetried', CANCEL_TASK: 'cancelTask',
};
const ID = 'r';

async function apply(h, { action, data }) {
  const m = METHOD[action];
  return 'task' in data ? h[m](ID, data.task) : h[m](ID);
}
const viewToState = (v) => v === null
  ? { status: 'none', task0: 'none', task1: 'none', task2: 'none' }
  : { ...v };

test('implementation matches the spec on every reachable state and action', async () => {
  spec.init();
  const start = spec.getState();
  const paths = new Map([[stable(start), []]]);
  const queue = [start];
  let checked = 0;
  while (queue.length) {
    const pre = queue.shift();
    const path = paths.get(stable(pre));
    for (const step of STEPS) {
      spec.setState(pre);
      spec.actions[step.action](step.data);
      const specPost = spec.getState();
      const h = await createHost();
      for (const p of path) assert.equal((await apply(h, p)).ok, true);
      assert.deepEqual(viewToState(await h.run(ID)), pre);
      const out = await apply(h, step);
      const implPost = viewToState(await h.run(ID));
      const ctx = `${JSON.stringify(pre)} ${step.action} ${JSON.stringify(step.data)}`;
      assert.deepEqual(implPost, specPost, ctx);
      assert.equal(out.ok, stable(specPost) !== stable(pre), ctx);
      if (!out.ok) assert.equal(typeof out.reason, 'string');
      checked++;
      if (!paths.has(stable(specPost))) {
        paths.set(stable(specPost), [...path, step]);
        queue.push(specPost);
      }
    }
  }
  console.log(`reachable states: ${paths.size}, steps checked: ${checked}`);
  assert.ok(checked > 3000);
});

