// @ts-nocheck -- node:test types are not installed
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('start, unknown runs, duplicates', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued', paused: false });
});

test('happy path to completed, then closed', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('r', t)).ok, true);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r')).status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('mixed queued/running is running; all evicted is evicted', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskStarted('r', 0);
  await h.taskStarted('r', 2);
  for (const t of [0, 1, 2]) await h.taskEvicted('r', t);
  assert.equal((await h.run('r')).status, 'evicted');
  await h.taskRequeued('r', 0);
  assert.equal((await h.run('r')).status, 'running');
});

test('a failed run still accepts commands, and a retry requeues the failed task', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'queued', task2: 'queued', paused: false });
  assert.equal((await h.taskStarted('r', 1)).ok, true);
  assert.equal((await h.run('r')).status, 'failed');
  assert.equal((await h.taskRetried('r', 1)).ok, false);
  assert.deepEqual(await h.taskRetried('r', 0), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'running', task2: 'queued', paused: false });
  for (const t of [0, 2]) await h.taskStarted('r', t);
  for (const t of [0, 1, 2]) await h.taskCompleted('r', t);
  assert.equal((await h.run('r')).status, 'completed');
});

test('cancelling a failed run keeps the failure; retry after that', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.deepEqual(await h.cancel('r'), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled', paused: false });
  assert.equal((await h.cancel('r')).ok, false); // nothing in flight
  await h.taskRetried('r', 0);
  assert.equal((await h.run('r')).status, 'running');
  await h.cancel('r');
  assert.equal((await h.run('r')).status, 'cancelled');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
});

test('all tasks failed: run failed, retries allowed', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { await h.taskStarted('r', t); await h.taskFailed('r', t); }
  assert.equal((await h.run('r')).status, 'failed');
  assert.equal((await h.taskRetried('r', 2)).ok, true);
  assert.equal((await h.taskRetried('r', 3)).ok, false);
});

test('cancel: completed tasks stay, run is cancelled', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancel('r'), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled', paused: false });
  assert.equal((await h.cancel('r')).ok, false);
});

test('bad moves and bad task numbers are refused and change nothing', async () => {
  const h = await createHost();
  await h.start('r');
  const before = await h.run('r');
  for (const bad of [-1, 3, 1.5, NaN]) assert.equal((await h.taskStarted('r', bad)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskEvicted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  const res = await h.taskFailed('r', 0);
  assert.equal(res.ok, false);
  assert.equal(typeof res.reason, 'string');
  assert.deepEqual(await h.run('r'), before);
});

test('cancelTask cancels one in-flight task and re-derives the status', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancelTask('r', 1), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'cancelled', task2: 'queued', paused: false });
  assert.equal((await h.cancelTask('r', 1)).ok, false); // final
  assert.equal((await h.cancelTask('r', 3)).ok, false);
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.equal((await h.cancelTask('r', 0)).ok, false); // failed is final
  assert.equal((await h.cancelTask('r', 2)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled', paused: false });
});

test('cancelling the last in-flight task beside completed ones cancels the run', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1]) { await h.taskStarted('r', t); await h.taskCompleted('r', t); }
  await h.taskStarted('r', 2);
  await h.cancelTask('r', 2);
  assert.equal((await h.run('r')).status, 'cancelled');
  assert.equal((await h.taskRetried('r', 2)).ok, false);
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  const b = await createHost();
  await a.start('x');
  assert.equal(await b.run('x'), null);
});
